insert into public.workout_templates(slug,name,category,difficulty,focus,class_affinity,description,estimated_minutes,xp_reward,equipment,safety_notes,active,updated_at)
select slug,name,category,difficulty,focus,class_affinity,description,estimated_minutes,xp_reward,equipment,safety_notes,true,now() from w
on conflict (slug) do update set name=excluded.name,category=excluded.category,difficulty=excluded.difficulty,focus=excluded.focus,class_affinity=excluded.class_affinity,description=excluded.description,estimated_minutes=excluded.estimated_minutes,xp_reward=excluded.xp_reward,equipment=excluded.equipment,safety_notes=excluded.safety_notes,active=true,updated_at=now();

-- Replace template steps so the seed is deterministic.
delete from public.workout_steps where workout_id in (select id from public.workout_templates where slug in ('push-foundation','push-strength-i','push-strength-ii','pull-foundation','pull-strength-i','pull-strength-ii','handstand-foundation','handstand-balance','handstand-press-path','muscle-up-prep','planche-base','planche-advanced','front-lever-base','front-lever-advanced','back-lever-base','human-flag-prep','core-foundation','l-sit-path','dragon-flag-prep','leg-foundation','single-leg-strength','mobility-reset','shoulder-mobility-control','runner-base','five-k-builder','conditioning-circuit','full-body-initiation','full-body-ascension','recovery-flow'));

